#/**********************************************************************************************************************
# *  FILE DESCRIPTION
# *  -------------------------------------------------------------------------------------------------------------------
# *         File:  gen_vector_rte_declaration.py
# *    Component:  MICROSAR Run-Time Interface ARTI and Lauterbach TRACE32
# *
# *  Description:  Generator to generate TRACE32 script with runnable declarations out of Vector VFB Hooks
# *                implementation for ARTI. This script scans the "Rte_Hook_Arti.c" source file and generates
# *                the "rte_runnable.cmm" script.
# *                For support needs please contact support@lauterbach.com
# *                Use the keyword: "MICROSAR Run-Time Interface Lauterbach".
# *
# *                All VFB Hooks are filtered by SchM_Schedulable_ and Rte_Runnable_
# *********************************************************************************************************************/

#/**********************************************************************************************************************
# *	USER SPECIFIC SECTION:
# *	Change here AUTOSAR Project specific settings
# *********************************************************************************************************************/

# !! Change file paths here !!
fsrc=open("../Source/Rte_Hook_Arti.c",'r')                 # Generated by RTE
cmmdest=open("./rte_runnable.cmm",'w')                      # Generated by this Script

# !! Change VFB hook prefix filters here !!
and_keywords = ['#ID']
or_keywords = ['Rte_Runnable_','SchM_Schedulable_']
components_keywords = ['EcuM_','ComM_','BswM_','Dcm_','Can_','Fee_','NvM_','Rtm_','Xcp_']

# *********************************************************************************************************************/

def GET_RunnableName(str):
    if or_keywords[0] in str:
        start=or_keywords[0]   #'Rte_Runnable_'
    elif or_keywords[1] in str:
        start=or_keywords[1]   #'SchM_Schedulable_'
    end='_Start'

    for component in components_keywords:
        if component in str:
            strnew = (str.split(start))[1].split(end)[0]
            strsplit = (strnew.split(component,1))
            str = start + strsplit[1] + end

    return ((str.split(start))[1].split(end)[0])

while True:
    line = fsrc.readline()
    if all(y in line for y in and_keywords):
        if any(x in line for x in or_keywords):
            if ("_Start" in line):
                line=line.rstrip(); #remove the ^M (carriage return)
                name_start = line.find("#ID") + 3
                name_end   = line.rfind("_Start") + 6
                name_func  = line[name_start:name_end]
                id_start   = name_end
                id_end     = line.rfind("*/")
                id_value   = line[id_start:id_end].strip()
                cmmdest.write("TASK.CREATE.RUNNABLE "+name_func+" "+id_value+". "+'\"'+GET_RunnableName(name_func)+'\"'+'\n')
            elif ("_Return(" in line):
                pass
            print(line)
    if not line: break

fsrc.close()
cmmdest.close()
